return {npc02001={id="npc02001",dsc="原万灵教的成员，后因触犯教规被流放，走投无路时靠着一身万灵教的功夫加入重光教，被瓦尔塔所用。此时的他已经受伤，伤口流出的鲜血透过衣服滴在地面上。",sex="男",age=35,looks=20,showequip={},withCorpse=0},npc02002={id="npc02002",dsc="原万灵教的成员，后因触犯教规被流放，走投无路时靠着一身万灵教的功夫加入重光教，被瓦尔塔所用。此时他明显有些体力不支，正在一棵树下处理自己的伤口。",sex="男",age=35,looks=20,showequip={},withCorpse=0},npc02003={id="npc02003",title="打更人",dsc="瓦尔塔得力下属之一，长相吓人，左脸上还有一道从额头到嘴角的疤痕贯穿整个面部。",sex="男",age=40,looks=15,showequip={"重剑"},withCorpse=0},npc02004={id="npc02004",dsc="原万灵教的成员，后因触犯教规被流放，走投无路时靠着一身万灵教的功夫加入重光教，被瓦尔塔所用。他的衣服已经被伤口透出的鲜血浸染。",sex="男",age=35,looks=20,showequip={},withCorpse=0},npc02005={id="npc02005",dsc="重光教十二侍从之一，来自安息的一名守陵人。始终穿着连帽斗篷遮住脸，看不清长相。",sex="男",age=21,looks=0,showequip={"舍施尔弯刀"},withCorpse=0},npc02006={id="npc02006",title="猎手",dsc="瓦尔塔直属的暗杀组成员，带着宽大的帽子，脸上还有黑布遮蔽，很难看清长相。",sex="男",age=43,looks=0,showequip={"双钩"},withCorpse=0},npc02007={id="npc02007",dsc="从穿着来看应该是名匠人，但此时他蓬头垢面，衣服全是泥土，袖口沾着已经干涸的血迹，非常狼狈。",sex="男",age=66,looks=15,showequip={},withCorpse=0},npc02008={id="npc02008",dsc="此人以黑布遮面，看不清长相。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02009={id="npc02009",dsc="他头上扎着狼尾辫，身披灰色狼皮，面目凶狠吓人。",sex="男",age=28,looks=18,showequip={},withCorpse=0},npc02010={id="npc02010",dsc="此人身穿黑衣长相有些猥琐，脸上有一个狭长的疤痕。",sex="男",age=25,looks=13,showequip={},withCorpse=0},npc02011={id="npc02011",dsc="此人身着黑衣，身材魁梧，一身的肌肉将衣服撑满，看起来很难对付。",sex="男",age=30,looks=18,showequip={},withCorpse=0},npc02012={id="npc02012",dsc="此人身穿黑衣，长相有些猥琐。",sex="男",age=30,looks=14,showequip={},withCorpse=0},npc02013={id="npc02013",dsc="此人身穿黑衣，贼眉鼠眼不知道在想些什么。",sex="男",age=33,looks=13,showequip={},withCorpse=0},npc02014={id="npc02014",dsc="此人身穿黑衣，身材有些消瘦，但从腿上鼓起的肌肉来看，此人腿上功夫了得。",sex="男",age=29,looks=17,showequip={},withCorpse=0},npc02015={id="npc02015",dsc="它通身的毛发黝黑发亮，不掺一丝杂色，足有一人之高，牙尖爪利。它身子半伏，不断自喉中发出低吼，目光凶狠，叫人望而生却。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02016={id="npc02016",dsc="一身雪白的毛发十分罕见，并未伏身作攻击状，一直立于另外两只灰狼身后，竟似在用狼眸探究着你。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02017={id="npc02017",dsc="虽是常见的毛色，但其身形健壮，目露阴狠，龇牙咧嘴，低吼不断，看着凶狠非常。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02018={id="npc02018",dsc="棕色的毛发水亮，其上还泛着一些红，虽体型较为瘦小，但其身形矫健，稍不注意就会挨上一击。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02019={id="npc02019",dsc="它背覆黑毛，腹部雪白，呈乌云盖雪之势。它的双眼是罕见的蓝色，眉中的一点白毛与两条白眉好似三团火焰，看着威风凛凛。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02020={id="npc02020",dsc="它身体呈伏击之势，龇牙咧嘴，随时都会攻上前来。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02021={id="npc02021",dsc="它半伏着身体一动不动，眼睛直直地盯着你，只要你一露出破绽，它就会毫不犹豫地出击。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02022={id="npc02022",dsc="它一直在你的不远处缓步移动，耐心的寻找着你的破绽。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},npc02023={id="npc02023",dsc="恶狼浑身黝黑发亮，体型硕大，面目狰狞呲牙低吼，眼中充满嗜血凶狠的目光。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0}}0000000000